using namespace std;

// Huffman tree node structure
struct Node {
    char data;
    unsigned freq;
    Node *left, *right;

    Node(char data, unsigned freq)
        : data(data), freq(freq), left(nullptr), right(nullptr) {}
};

// Compare nodes based on frequency
struct Compare {
    bool operator()(const Node* l, const Node* r) {
        return l->freq > r->freq;
    }
};

// Function to print Huffman codes
void printCodes(Node* root, string str, map<char, string>& huffmanCodes) {
    if (!root) return;

    if (root->data != '$')
        huffmanCodes[root->data] = str;

    printCodes(root->left, str + "0", huffmanCodes);
    printCodes(root->right, str + "1", huffmanCodes);
}

// Huffman encoding function
string huffmanEncode(string text) {
    unordered_map<char, int> freqMap;
    for (char c : text) {
        freqMap[c]++;
    }

    priority_queue<Node*, vector<Node*>, Compare> pq;
    for (auto pair : freqMap) {
        pq.push(new Node(pair.first, pair.second));
    }

    while (pq.size() > 1) {
        Node* left = pq.top(); pq.pop();
        Node* right = pq.top(); pq.pop();

        pq.push(new Node('$', left->freq + right->freq));
        pq.push(left);
        pq.push(right);
    }

    Node* root = pq.top();
    map<char, string> huffmanCodes;
    printCodes(root, "", huffmanCodes);

    string encodedText = "";
    for (char c : text) {
        encodedText += huffmanCodes[c];
    }

    return encodedText;
}

// Huffman decoding function
string huffmanDecode(string encodedText, Node* root) {
    string decodedText = "";
    Node* currentNode = root;

    for (char bit : encodedText) {
        if (bit == '0') {
            currentNode = currentNode->left;
        } else {
            currentNode = currentNode->right;
        }

        if (currentNode->data != '$') {
            decodedText += currentNode->data;
            currentNode = root;
        }
    }

    return decodedText;
}

int main() {
    string text = "Huffman coding is a popular data compression algorithm.";
    string encodedText = huffmanEncode(text);
    cout << "Original text: " << text << endl;
    cout << "Encoded text: " << encodedText << endl;

    // Reconstruct the Huffman tree for decoding
    unordered_map<char, int> freqMap;
    for (char c : text) {
        freqMap[c]++;
    }

    priority_queue<Node*, vector<Node*>, Compare> pq;
    for (auto pair : freqMap) {
        pq.push(new Node(pair.first, pair.second));
    }

    Node* root = pq.top();

    string decodedText = huffmanDecode(encodedText, root);
    cout << "Decoded text: " << decodedText << endl;

    return 0;
}
